/**
 * Use real bytes and pathname replacement interleavings to verify the portable-integrity reader.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - variable roots: line 21
 * - function fixture: line 22
 * - variable hash: line 30
 * @@SYMBOL_INDEX_END
 */
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import { afterEach, describe, expect, it, vi } from "vitest";
const { payloadHashes } = createRequire(import.meta.url)("../../desktop/tests/payload.cjs") as {
  payloadHashes: (
    directory: string,
    limits?: { maxEntries: number; maxFileBytes: number; maxTotalBytes: number },
  ) => Promise<Record<string, string>>;
};
const roots: string[] = [];
function fixture() {
  fs.mkdirSync(".runtime", { recursive: true });
  const root = fs.mkdtempSync(path.resolve(".runtime/payload-read-"));
  roots.push(root);
  const directory = path.join(root, "payload");
  fs.mkdirSync(directory);
  return { root, directory };
}
const hash = (value: string) => createHash("sha256").update(value).digest("hex");
afterEach(() => {
  vi.restoreAllMocks();
  for (const root of roots.splice(0)) {
    if (!root.startsWith(path.resolve(".runtime") + path.sep))
      throw new Error("Not an owned fixture.");
    fs.rmSync(root, { recursive: true, force: true });
  }
});
describe("actual portable payload descriptor integrity", () => {
  it("hashes exact bytes and stable relative names without including directories", async () => {
    const { directory } = fixture();
    fs.writeFileSync(path.join(directory, "one.txt"), "abc");
    fs.mkdirSync(path.join(directory, "nested"));
    fs.writeFileSync(path.join(directory, "nested", "two.txt"), "");
    expect(await payloadHashes(directory)).toEqual({
      "one.txt": "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
      "nested/two.txt": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
    });
  });
  it("binds replacement before open to the actual new descriptor, not an older pathname size", async () => {
    const { root, directory } = fixture(),
      name = path.join(directory, "input");
    fs.writeFileSync(name, "abc");
    const actual = fs.openSync;
    let swapped = false;
    vi.spyOn(fs, "openSync").mockImplementation((value, flags, mode) => {
      if (String(value) === name && !swapped) {
        swapped = true;
        fs.renameSync(name, path.join(root, "prior"));
        fs.writeFileSync(name, "replacement bytes");
      }
      return actual(value, flags, mode);
    });
    expect(await payloadHashes(directory)).toEqual({ input: hash("replacement bytes") });
    expect(fs.readFileSync(path.join(root, "prior"), "utf8")).toBe("abc");
  });
  it("refuses replacement after open when the named file no longer identifies that descriptor", async () => {
    const { root, directory } = fixture(),
      name = path.join(directory, "input");
    fs.writeFileSync(name, "original");
    const actual = fs.openSync;
    let swapped = false;
    vi.spyOn(fs, "openSync").mockImplementation((value, flags, mode) => {
      const fd = actual(value, flags, mode);
      if (String(value) === name && !swapped) {
        swapped = true;
        fs.renameSync(name, path.join(root, "prior"));
        fs.writeFileSync(name, "different");
      }
      return fd;
    });
    await expect(payloadHashes(directory)).rejects.toThrow(/single-link file/u);
    expect(fs.readFileSync(name, "utf8")).toBe("different");
  });
  it("refuses actual hardlink aliases without changing either file", async () => {
    const { root, directory } = fixture(),
      other = path.join(root, "unrelated");
    fs.writeFileSync(other, "preserved");
    fs.linkSync(other, path.join(directory, "linked"));
    await expect(payloadHashes(directory)).rejects.toThrow(/single-link/u);
    expect(fs.readFileSync(other, "utf8")).toBe("preserved");
  });
  it("refuses a real directory junction/symlink before following it", async () => {
    const { root, directory } = fixture(),
      outside = path.join(root, "unrelated");
    fs.mkdirSync(outside);
    fs.writeFileSync(path.join(outside, "value"), "preserved");
    fs.symlinkSync(outside, path.join(directory, "linked"), "junction");
    await expect(payloadHashes(directory)).rejects.toThrow(/aliases/u);
    expect(fs.readFileSync(path.join(outside, "value"), "utf8")).toBe("preserved");
  });
  it("enforces per-file and total byte caps before reading excessive bytes", async () => {
    const { directory } = fixture();
    fs.writeFileSync(path.join(directory, "one"), "1234567890");
    fs.writeFileSync(path.join(directory, "two"), "1234567890");
    await expect(
      payloadHashes(directory, { maxEntries: 3, maxFileBytes: 8, maxTotalBytes: 16 }),
    ).rejects.toThrow(/bounded input/u);
    await expect(
      payloadHashes(directory, { maxEntries: 3, maxFileBytes: 12, maxTotalBytes: 16 }),
    ).rejects.toThrow(/bounded input/u);
  });
  it("stops at the entry budget without opening later entries", async () => {
    const { directory } = fixture();
    for (const name of ["one", "two", "three"])
      fs.writeFileSync(path.join(directory, name), "bytes");
    const opening = vi.spyOn(fs, "openSync");
    await expect(
      payloadHashes(directory, { maxEntries: 1, maxFileBytes: 8, maxTotalBytes: 16 }),
    ).rejects.toThrow(/entry budget/u);
    expect(opening).toHaveBeenCalledTimes(1);
  });
  it("does not allow test limits to relax production caps", async () => {
    const { directory } = fixture();
    await expect(
      payloadHashes(directory, { maxEntries: 1025, maxFileBytes: 8, maxTotalBytes: 16 }),
    ).rejects.toThrow(/Invalid bounded/u);
    await expect(
      payloadHashes(directory, { maxEntries: 1, maxFileBytes: Number.NaN, maxTotalBytes: 16 }),
    ).rejects.toThrow(/Invalid bounded/u);
  });
});
